16: @Service
17: @RequiredArgsConstructor
18: @Transactional
19: public class CourtService {
20:   private final CourtDao courts;
21:   private final SurfaceDao surfaces;
22:   private final MutationGuard guard;
23: 
24:   private Court find(long id) {
25:     return courts
26:         .find(id)
27:         .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "Court not found"));
28:   }
29: 
30:   @Transactional(readOnly = true)
31:   public CourtResponse get(long id) {
32:     return CourtResponse.from(find(id));
33:   }
34: 
35:   @Transactional(readOnly = true)
36:   public List<CourtResponse> list() {
37:     return courts.list().stream().map(CourtResponse::from).toList();
38:   }
39: 
40:   public CourtResponse create(CourtRequest request) {
41:     guard.lock();
42:     Court court = new Court();
43:     updateValues(court, request.fields(), false);
44:     courts.persist(court);
45:     return CourtResponse.from(court);
46:   }
47: 
48:   public CourtResponse update(long id, CourtRequest request, boolean partial) {
49:     guard.lock();
50:     Court court = find(id);
51:     updateValues(court, request.fields(), partial);
52:     return CourtResponse.from(court);
53:   }
54: 
55:   private void updateValues(Court court, Map<String, Object> input, boolean partial) {
56:     Input.fields(input, Set.of("courtNumber", "surfaceId"), partial);
57:     long number =
58:         input.containsKey("courtNumber")
59:             ? Input.positiveInteger(input.get("courtNumber"))
60:             : court.getCourtNumber();
61:     if (number > Integer.MAX_VALUE) {
62:       throw Input.invalid("Court number is too large");
63:     }
64:     Surface surface =
65:         input.containsKey("surfaceId")
66:             ? surfaces
67:                 .find(Input.positiveInteger(input.get("surfaceId")))
68:                 .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "Surface not found"))
69:             : court.getSurface();
70:     if (courts.exists((int) number, court.getId())) {
71:       throw new ApiException(HttpStatus.CONFLICT, "Court number already exists");
72:     }
73:     court.update((int) number, surface);
74:   }
75: 
76:   public void delete(long id) {
77:     guard.lock();
78:     find(id).softDelete();
79:   }
80: }

